	memcpy(dht, alt_dht, dht->size);
	hpack_dht_free(alt_dht);

	return dht;
}

static inline void hpack_dht_init(struct hpack_dht *dht, uint32_t size) /* <=== hpack_dht_init */ 
{
	dht->size = size;
	dht->total = 0;
	dht->used = 0;
}

